export function computeInvoice({ lines, discountKobo = 0 }) {
  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }
  if (discountKobo < 0) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }
  for (const line of lines) {
    if (typeof line.sku !== 'string' || line.unitPriceKobo < 0 || !Number.isInteger(line.unitPriceKobo) || line.qty < 1 || !Number.isInteger(line.qty) || typeof line.vatExempt !== 'boolean') {
      throw new RangeError("Invalid line data");
    }
  }

  const invoiceSubtotalKobo = lines.reduce((sum, line) => sum + line.unitPriceKobo * line.qty, 0);
  const appliedDiscountKobo = Math.min(discountKobo, invoiceSubtotalKobo);
  const discountAllocation = lines.map(line => Math.floor(appliedDiscountKobo * line.unitPriceKobo * line.qty / invoiceSubtotalKobo));
  const leftoverKobo = appliedDiscountKobo - discountAllocation.reduce((sum, alloc) => sum + alloc, 0);
  const largestRemainders = lines.map((line, index) => ({
    index,
    remainder: (appliedDiscountKobo * line.unitPriceKobo * line.qty / invoiceSubtotalKobo - Math.floor(appliedDiscountKobo * line.unitPriceKobo * line.qty / invoiceSubtotalKobo)) * 100
  })).sort((a, b) => b.remainder - a.remainder);
  for (let i = 0; i < leftoverKobo; i++) {
    discountAllocation[largestRemainders[i].index]++;
  }

  const linesWithVat = lines.filter(line => !line.vatExempt);
  const vatKobo = linesWithVat.reduce((sum, line) => sum + Math.round(line.netKobo * 0.075), 0);
  const totalKobo = invoiceSubtotalKobo - appliedDiscountKobo + vatKobo;

  return {
    subtotalKobo: invoiceSubtotalKobo,
    discountKobo: appliedDiscountKobo,
    vatKobo: vatKobo,
    totalKobo: totalKobo,
    lines: lines.map((line, index) => ({
      ...line,
      subtotalKobo: line.unitPriceKobo * line.qty,
      discountKobo: discountAllocation[index],
      netKobo: line.subtotalKobo - discountAllocation[index],
      vatKobo: line.vatExempt ? 0 : Math.round(line.netKobo * 0.075)
    }))
  };
}
